-- Athena saved query (Product_B2C_Intl)
-- ID: 09003dbe-e3f5-432c-aef1-1882dda853a6
-- Name: User Profiling Perz - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH search_data AS ( -- Step 1: Grab search data along with your dimensions SELECT mri_session_id, rb_user_id, channel, os AS os,user_type FROM user_interaction.search_details WHERE __time >= TIMESTAMP '2026-04-20 00:00:00' AND __time < TIMESTAMP '2026-04-21 00:00:00' AND country = 'IND' AND tp_channel = 'INVALID' ), distinct_search_clients AS ( -- Step 2: Clean list of rb_user_id IDs to filter the user_data dataset efficiently SELECT DISTINCT rb_user_id FROM search_data ), filtered_user_data AS ( -- Step 3: Collapse user_data rows to 1 per rb_user_id and grab their user_type SELECT u.user_id, MAX(CASE WHEN u.date_of_birth IS NOT NULL THEN 1 ELSE 0 END) AS has_yob, MAX(CASE WHEN u.gender IS NOT NULL AND u.gender <> '' THEN 1 ELSE 0 END) AS has_gender, MAX(CASE WHEN u.primary_mobile_no IS NOT NULL AND u.primary_mobile_no <> '' THEN 1 ELSE 0 END) AS has_phone, MAX(CASE WHEN u.primary_email_id IS NOT NULL AND u.primary_email_id <> '' THEN 1 ELSE 0 END) AS has_email FROM capi.user_data u INNER JOIN distinct_search_clients d ON u.user_id = d.rb_user_id GROUP BY u.user_id ), aggregated_metrics AS ( -- Step 4: Join tables and group by the requested granular dimensions SELECT s.channel, s.os, -- upper(s.user_type) AS user_type, COUNT(DISTINCT s.mri_session_id) AS total_sessions_in_search, COUNT(DISTINCT s.rb_user_id) AS total_distinct_rb_user_ids_in_search, COUNT(DISTINCT r.user_id) AS total_distinct_clients_joined, COUNT(DISTINCT CASE WHEN r.has_yob = 1 THEN r.user_id END) AS total_joined_with_yob, COUNT(DISTINCT CASE WHEN r.has_gender = 1 THEN r.user_id END) AS total_joined_with_gender, COUNT(DISTINCT CASE WHEN r.has_phone = 1 THEN r.user_id END) AS total_joined_with_phone, COUNT(DISTINCT CASE WHEN r.has_email = 1 THEN r.user_id END) AS total_joined_with_email FROM search_data s LEFT JOIN filtered_user_data r ON s.rb_user_id = r.user_id GROUP BY 1,2 -- ,3 ) -- Step 5: Output all segments with their respective matching percentages SELECT channel, os, -- user_type, total_sessions_in_search, total_distinct_rb_user_ids_in_search, total_distinct_clients_joined, ROUND(100.0 * total_distinct_clients_joined / NULLIF(total_distinct_rb_user_ids_in_search, 0), 2) AS pct_users_found_in_rum, ROUND(100.0 * total_joined_with_yob / NULLIF(total_distinct_rb_user_ids_in_search, 0), 2) AS pct_searching_users_with_age, ROUND(100.0 * total_joined_with_gender / NULLIF(total_distinct_rb_user_ids_in_search, 0), 2) AS pct_searching_users_with_gender, ROUND(100.0 * total_joined_with_phone / NULLIF(total_distinct_rb_user_ids_in_search, 0), 2) AS pct_searching_users_with_phone, ROUND(100.0 * total_joined_with_email / NULLIF(total_distinct_rb_user_ids_in_search, 0), 2) AS pct_searching_users_with_email FROM aggregated_metrics ORDER BY total_sessions_in_search DESC;
